<?php
declare(strict_types=1);
$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-'.bin2hex(random_bytes(5));function kalite_filo_admin_config():array{global $root;return['data_root'=>$root];}function kalite_filo_admin_ensure_private_directory(string $path):void{if(!is_dir($path)&&!mkdir($path,0700,true)&&!is_dir($path))throw new RuntimeException('directory');}function kalite_filo_admin_vehicle_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'vehicles.json';}function kalite_filo_admin_article_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'articles.json';}function kalite_filo_admin_media_catalog_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'media'.DIRECTORY_SEPARATOR.'library'.DIRECTORY_SEPARATOR.'library.json';}function kalite_filo_admin_assert_vehicle_uniqueness(array $records):void{$seen=[];foreach($records as $record){$key=($record['id']??'').'|'.($record['sourceId']??'').'|'.($record['slug']??'');if(isset($seen[$key]))throw new InvalidArgumentException();$seen[$key]=true;}}function kalite_filo_admin_vehicle_records():array{$records=[];foreach(range(1,4)as$i)$records[]=['id'=>'vehicle-'.$i,'sourceId'=>'SOURCE-'.$i,'slug'=>'vehicle-'.$i,'featured'=>true,'publicationStatus'=>'published','priceAmountMinor'=>10000,'coverImage'=>['src'=>'/vehicle.jpg']];return$records;}function kalite_filo_admin_article_drafts():array{return[['id'=>'article-one','coverMediaId'=>null,'locales'=>['tr'=>['status'=>'ready']]]];}function kalite_filo_admin_media_records():array{return[['id'=>str_repeat('a',32),'checksum'=>str_repeat('b',64)]];}function kalite_filo_admin_taxonomy():array{return['make'=>[['value'=>'Renault']]];}function kalite_filo_admin_content_snapshot():array{return['articles'=>['records'=>[]]];}function publish_assert(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}function publish_remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[]as$entry){if($entry==='.'||$entry==='..')continue;$item=$path.DIRECTORY_SEPARATOR.$entry;is_dir($item)?publish_remove($item):@unlink($item);}@rmdir($path);}require_once dirname(__DIR__).'/publishing-store.php';
try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$changes=kalite_filo_admin_unpublished_changes();publish_assert(count($changes)===2&&strlen($changes[0]['fingerprint'])===64,'Changes must use content fingerprints.');$request=kalite_filo_admin_create_staging_publish_request();publish_assert($request['status']==='awaiting_runner'&&$request['target']==='staging'&&strlen($request['snapshotHash'])===64,'Staging request must freeze a runner-pending snapshot.');$duplicate=kalite_filo_admin_create_staging_publish_request();publish_assert($duplicate['id']===$request['id'],'The same pending snapshot must be idempotent.');$loaded=kalite_filo_admin_publish_request($request['id']);publish_assert(is_array($loaded)&&($loaded['snapshotHash']??null)===$request['snapshotHash'],'A valid request must be available to the trusted runner handoff.');publish_assert(kalite_filo_admin_publish_request('../'.$request['id'])===null&&kalite_filo_admin_publish_request('publish-invalid')===null,'Runner handoff lookup must reject traversal and malformed IDs.');$safe=kalite_filo_admin_safe_publish_request($request);publish_assert(!array_key_exists('snapshot',$safe)&&!array_key_exists('fingerprint',$safe['changes'][0])&&$safe['changeCount']===2,'Browser history must not expose private snapshot fingerprints.');publish_assert(count(kalite_filo_admin_publish_requests())===1,'Private request history must round-trip.');$requestDirectory=kalite_filo_admin_publish_root().DIRECTORY_SEPARATOR.'requests';file_put_contents($requestDirectory.DIRECTORY_SEPARATOR.'publish-99999999-999999-abcdef123456.json','{"broken"');publish_assert(count(kalite_filo_admin_publish_requests())===1,'A malformed history record must not break the complete publishing overview.');file_put_contents(kalite_filo_admin_publish_baseline_path(),'{"broken"');file_put_contents(kalite_filo_admin_publish_baseline_snapshot_path(),'{"broken"');publish_assert(kalite_filo_admin_publish_baseline()===[]&&kalite_filo_admin_publish_baseline_record()===[]&&kalite_filo_admin_publish_baseline_snapshot()===null,'Malformed baseline files must degrade safely.');$invalid=kalite_filo_admin_staging_publish_payload();$invalid['featuredVehicleIds']=['vehicle-1'];publish_assert(kalite_filo_admin_validate_staging_publish_payload($invalid)['valid']===false,'Featured invariant must block publish.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing store tests passed.\n");

$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-result-'.bin2hex(random_bytes(5));
try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$request=kalite_filo_admin_create_staging_publish_request();$hash=$request['snapshotHash'];try{kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',[]);throw new RuntimeException('Completion before start must fail.');}catch(DomainException){}try{kalite_filo_admin_transition_publish_request($request['id'],str_repeat('0',64),'start');throw new RuntimeException('Wrong snapshot hash must fail.');}catch(InvalidArgumentException){}$running=kalite_filo_admin_transition_publish_request($request['id'],$hash,'start');publish_assert($running['status']==='running'&&is_string($running['startedAt']),'Start must enter running state.');publish_assert(kalite_filo_admin_transition_publish_request($request['id'],$hash,'start')['startedAt']===$running['startedAt'],'Repeated start must be idempotent.');$stages=array_fill_keys(['materialization','validation','build','release','deployment','smoke'],'passed');$result=['outcome'=>'succeeded','manifestHash'=>str_repeat('a',64),'artifactHash'=>str_repeat('b',64),'stages'=>$stages,'summary'=>'Staging checks passed.'];$complete=kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',$result);publish_assert($complete['status']==='staging_succeeded'&&($complete['result']['reportedBy']??null)==='owner','Successful completion must become terminal and retain reporter identity.');publish_assert(kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',$result)['completedAt']===$complete['completedAt'],'Repeated identical completion must be idempotent.');publish_assert(kalite_filo_admin_unpublished_changes()===[],'A successful staging result must become the unpublished-change baseline.');$invalidStages=$stages;$invalidStages['smoke']='skipped';try{kalite_filo_admin_normalize_runner_result(['outcome'=>'succeeded','manifestHash'=>str_repeat('a',64),'artifactHash'=>str_repeat('b',64),'stages'=>$invalidStages]);throw new RuntimeException('Successful result with skipped stage must fail.');}catch(InvalidArgumentException){}try{kalite_filo_admin_normalize_runner_result(['outcome'=>'failed','manifestHash'=>str_repeat('a',64),'artifactHash'=>'','stages'=>$stages]);throw new RuntimeException('Failed result without failed stage must fail.');}catch(InvalidArgumentException){}$failedStages=$stages;$failedStages['materialization']='failed';foreach(['validation','build','release','deployment','smoke']as$stage)$failedStages[$stage]='skipped';$earlyFailure=kalite_filo_admin_normalize_runner_result(['outcome'=>'failed','manifestHash'=>'','artifactHash'=>'','stages'=>$failedStages]);publish_assert($earlyFailure['manifestHash']===null,'A pre-materialization failure may omit unavailable hashes.');$staleQueued=$complete;$staleQueued['id']='publish-20200101-120000-abcdef123456';$staleQueued['status']='awaiting_runner';$staleQueued['requestedAt']='2020-01-01T12:00:00+00:00';$staleQueued['automation']=['status'=>'queued','updatedAt'=>'2020-01-01T12:00:00+00:00'];kalite_filo_admin_replace_publish_request($staleQueued);$staleRunning=$staleQueued;$staleRunning['id']='publish-20200101-130000-abcdef123456';$staleRunning['status']='running';$staleRunning['startedAt']='2020-01-01T13:00:00+00:00';$staleRunning['automation']=['status'=>'running','updatedAt'=>'2020-01-01T13:00:00+00:00'];kalite_filo_admin_replace_publish_request($staleRunning);$recent=$staleQueued;$recent['id']='publish-20990101-120000-abcdef123456';$recent['requestedAt']='2099-01-01T12:00:00+00:00';$recent['automation']=['status'=>'queued','updatedAt'=>'2099-01-01T12:00:00+00:00'];kalite_filo_admin_replace_publish_request($recent);$cleared=kalite_filo_admin_clear_publish_history();publish_assert($cleared['deleted']===2&&$cleared['deletedStale']===2&&$cleared['preservedCurrent']===1&&$cleared['preservedActive']===1,'History cleanup must retain the current release and recent work while deleting stale orphaned runs.');publish_assert(count(kalite_filo_admin_publish_requests())===2,'Current and genuinely recent records must remain visible.');publish_assert(kalite_filo_admin_unpublished_changes()===[],'Clearing history must preserve the successful baseline.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing result transition tests passed.\n");

$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-diff-'.bin2hex(random_bytes(5));
try {
    $before=['formatVersion'=>1,'vehicles'=>[['id'=>'vehicle-1','make'=>'Renault','model'=>'Clio','fuelLabel'=>'Benzin','publicationStatus'=>'published']]];
    $after=['formatVersion'=>1,'vehicles'=>[['id'=>'vehicle-1','make'=>'Renault','model'=>'Clio','fuelLabel'=>'Tam Hybrid','publicationStatus'=>'published']]];
    $details=kalite_filo_admin_vehicle_change_details($before,$after);
    publish_assert(count($details)===1&&$details[0]['entity']==='Renault Clio'&&$details[0]['fields'][0]['label']==='Yakıt'&&$details[0]['fields'][0]['before']==='Benzin'&&$details[0]['fields'][0]['after']==='Tam Hybrid','Vehicle publish history must retain bounded before/after field details.');
    $source=['id'=>'article-one','title'=>'Kurumsal Filoda Doğru Araç Nasıl Seçilir?','categoryId'=>'arac-rehberi','featured'=>false,'importDraft'=>['categoryId'=>'arac-rehberi','featured'=>false,'locales'=>['tr'=>['status'=>'ready','title'=>'Kurumsal Filoda Doğru Araç Nasıl Seçilir?','slug'=>'dogru-arac','excerpt'=>'Eski özet','markdown'=>'Eski metin'],'en'=>null]]];
    $articleBefore=['formatVersion'=>1,'articles'=>[],'articleSources'=>[$source]];$draft=$source['importDraft'];$draft['id']='article-one';$draft['locales']['tr']['status']='draft';$articleAfter=['formatVersion'=>1,'articles'=>[$draft],'articleSources'=>[$source]];$articleDetails=kalite_filo_admin_article_change_details($articleBefore,$articleAfter);
    publish_assert(count($articleDetails)===1&&$articleDetails[0]['action']==='updated'&&$articleDetails[0]['entityId']==='article-one'&&$articleDetails[0]['fields'][0]['label']==='Yayın durumu'&&$articleDetails[0]['fields'][0]['before']==='published'&&$articleDetails[0]['fields'][0]['after']==='unpublished','A published article moved to draft must be an entity update with an explicit publication-state diff.');
    kalite_filo_admin_write_publish_baseline(['id'=>'publish-20260902-120000-abcdef123456','snapshotHash'=>str_repeat('a',64),'changes'=>[],'snapshot'=>$after]);
    publish_assert(kalite_filo_admin_publish_baseline_snapshot()===$after,'The deployed snapshot must survive independently of request history.');
    $safe=kalite_filo_admin_safe_publish_request(['id'=>'publish-20260902-120000-abcdef123456','target'=>'staging','status'=>'staging_succeeded','changeCount'=>1,'changes'=>[['id'=>'change','type'=>'vehicles','label'=>'Araç taslakları','updatedAt'=>null,'details'=>$details]],'snapshotHash'=>str_repeat('a',64),'requestedAt'=>gmdate('c'),'requestedBy'=>'owner','startedAt'=>null,'completedAt'=>null,'result'=>null,'automation'=>null]);
    publish_assert(($safe['changes'][0]['details'][0]['fields'][0]['after']??null)==='Tam Hybrid'&&!array_key_exists('snapshot',$safe),'The browser-safe history may expose bounded diffs but never the private snapshot.');
} finally { publish_remove($root); }
fwrite(STDOUT,"Admin publishing change detail tests passed.\n");

publish_assert(kalite_filo_admin_publish_request_is_in_flight(['status'=>'awaiting_runner','automation'=>['status'=>'queued']]),'A queued staging snapshot must be classified as in flight.');
publish_assert(kalite_filo_admin_publish_request_is_in_flight(['status'=>'running','automation'=>['status'=>'deploying']]),'A deploying staging snapshot must be classified as in flight.');
publish_assert(!kalite_filo_admin_publish_request_is_in_flight(['status'=>'awaiting_runner','automation'=>['status'=>'dispatch_failed']]),'A failed dispatch must return its changes to the unpublished list.');
